// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.themeimport androidx.compose.foundation.isSystemInDarkThemeimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.darkColorSchemeimport androidx.compose.material3.lightColorSchemeimport androidx.compose.runtime.Composableimport androidx.compose.runtime.CompositionLocalProviderimport androidx.compose.runtime.staticCompositionLocalOfimport androidx.compose.ui.graphics.Brushimport androidx.compose.ui.graphics.Color/** * NOUS — Aurora Glass theme. * * Dark-first brand identity. Light theme supported for accessibility. * No dynamic colors — we want consistent NOUS brand across devices. */private val DarkColorScheme = darkColorScheme(    primary = AccentAuroraStart,    onPrimary = Color.White,    primaryContainer = AccentAuroraStart.copy(alpha = 0.15f),    onPrimaryContainer = TextPrimaryDark,    secondary = AccentAuroraEnd,    onSecondary = Color.Black,    tertiary = AccentWarm,    onTertiary = Color.White,    background = VoidDark,    onBackground = TextPrimaryDark,    surface = SurfaceDark,    onSurface = TextPrimaryDark,    surfaceVariant = ElevatedDark,    onSurfaceVariant = TextSecondaryDark,    surfaceTint = AccentAuroraStart,    inverseSurface = TextPrimaryDark,    inverseOnSurface = VoidDark,    error = AccentDanger,    onError = Color.White,    errorContainer = AccentDanger.copy(alpha = 0.15f),    onErrorContainer = AccentDanger,    outline = TextTertiaryDark,    outlineVariant = TextTertiaryDark.copy(alpha = 0.5f),    scrim = Color.Black,)private val LightColorScheme = lightColorScheme(    primary = AccentAuroraStart,    onPrimary = Color.White,    primaryContainer = AccentAuroraStart.copy(alpha = 0.10f),    onPrimaryContainer = TextPrimaryLight,    secondary = AccentAuroraEnd,    onSecondary = Color.Black,    tertiary = AccentWarm,    onTertiary = Color.White,    background = VoidLight,    onBackground = TextPrimaryLight,    surface = SurfaceLight,    onSurface = TextPrimaryLight,    surfaceVariant = ElevatedLight,    onSurfaceVariant = TextSecondaryLight,    surfaceTint = AccentAuroraStart,    inverseSurface = TextPrimaryLight,    inverseOnSurface = VoidLight,    error = AccentDanger,    onError = Color.White,    errorContainer = AccentDanger.copy(alpha = 0.10f),    onErrorContainer = AccentDanger,    outline = TextTertiaryLight,    outlineVariant = TextTertiaryLight.copy(alpha = 0.5f),    scrim = Color.Black,)/** * Local gradient brush for the aurora accent — accessible from any Composable. */val LocalAuroraBrush = staticCompositionLocalOf<Brush> {    Brush.linearGradient(listOf(AccentAuroraStart, AccentAuroraEnd))}/** * Local brain layer color map — used by BrainBar, BrainActivitySheet, etc. */val LocalBrainLayerColors = staticCompositionLocalOf<Map<String, Color>> {    mapOf(        "L0" to BrainL0,        "L1" to BrainL1,        "L2" to BrainL2,        "L3" to BrainL3,        "L4" to BrainL4,        "L5" to BrainL5,    )}@Composablefun NousTheme(    darkTheme: Boolean = isSystemInDarkTheme(),    content: @Composable () -> Unit,) {    val colorScheme = if (darkTheme) DarkColorScheme else LightColorScheme    val auroraBrush = Brush.linearGradient(        colors = listOf(AccentAuroraStart, AccentAuroraEnd),    )    CompositionLocalProvider(        LocalAuroraBrush provides auroraBrush,        LocalBrainLayerColors provides mapOf(            "L0" to BrainL0,            "L1" to BrainL1,            "L2" to BrainL2,            "L3" to BrainL3,            "L4" to BrainL4,            "L5" to BrainL5,        ),    ) {        MaterialTheme(            colorScheme = colorScheme,            typography = NousTypography,            shapes = NousShapes,            content = content,        )    }}/** * Resolve a brain layer name (e.g. "L4") to its color, with safe fallback. */fun brainLayerColor(layerName: String?): Color {    if (layerName == null) return TextTertiaryDark    return when (layerName.uppercase()) {        "L0", "INTENT" -> BrainL0        "L1", "RULE" -> BrainL1        "L2", "SKILL" -> BrainL2        "L3", "LOCAL", "LOCAL_LLM" -> BrainL3        "L4", "CLOUD", "CLOUD_LLM" -> BrainL4        "L5", "AGENTIC" -> BrainL5        else -> TextTertiaryDark    }}/** * Resolve a persona ID to its accent color, with safe fallback to aurora purple. */fun personaColor(personaId: String?): Color {    return when (personaId?.lowercase()) {        "atlas" -> PersonaAtlas        "nova" -> PersonaNova        "onyx" -> PersonaOnyx        "sage" -> PersonaSage        "echo" -> PersonaEcho        "vanguard" -> PersonaVanguard        "aria" -> PersonaAria        "wraith" -> PersonaWraith        "zenith" -> PersonaZenith        else -> PersonaAtlas    }}